#pragma once
#include <vector>
#include <cmath>
#include <cstring>
#include <algorithm>
#include <cstdint>
inline simParams_t studyParams(){simParams_t p{};p.gridSize={64,64,64};p.numCells=64*64*64;p.numBodies=16384;p.particleRadius=fParticleRadius;p.colliderPos={1.2f,-0.8f,0.8f};p.colliderRadius=fColliderRadius;p.worldOrigin={1.0f,-1.0f,-1.0f};float cell=p.particleRadius*2.0f;p.cellSize={cell,cell,cell};p.spring=.5f;p.damping=.02f;p.shear=.1f;p.attraction=0.f;p.boundaryDamping=-.5f;p.gravity={0.f,-.0003f,0.f};p.globalDamping=1.f;return p;}
struct CPUState{std::vector<double>pos,vel,prevel;};
inline void sphereForce(const double*a,const double*b,const double*va,const double*vb,double ra,double rb,const simParams_t&p,double*f){double rel[3],rv[3];double d2=0;for(int k=0;k<3;k++){rel[k]=b[k]-a[k];if(fabs(rel[k])>=ra+rb)return;d2+=rel[k]*rel[k];rv[k]=vb[k]-va[k];}double d=sqrt(d2);if(d>=ra+rb)return;if(d==0){fprintf(stderr,"CPU singular coincident centers\n");exit(7);}double n[3],dot=0;for(int k=0;k<3;k++){n[k]=rel[k]/d;dot+=rv[k]*n[k];}double spring=-double(p.spring)*(ra+rb-d);for(int k=0;k<3;k++){double tangent=rv[k]-dot*n[k];f[k]+=spring*n[k]+double(p.damping)*rv[k]+double(p.shear)*tangent+double(p.attraction)*rel[k];}}
inline void cpuStep(CPUState&s,const simParams_t&p){const size_t N=s.pos.size()/4;double lo=double(-1.f+p.particleRadius),hi=double(1.f-p.particleRadius);double gravity[3]={p.gravity.x,p.gravity.y,p.gravity.z};for(size_t i=0;i<N;i++){for(int k=0;k<3;k++){double&v=s.vel[4*i+k];double&x=s.pos[4*i+k];v=(v+gravity[k]*double(timestep))*double(p.globalDamping);x+=v*double(timestep);if(x<lo){x=lo;v*=double(p.boundaryDamping);}if(x>hi){x=hi;v*=double(p.boundaryDamping);}}s.pos[4*i+3]=1;s.vel[4*i+3]=0;}s.prevel=s.vel;std::vector<double>newvel=s.vel;const double cursor[4]={p.colliderPos.x,p.colliderPos.y,p.colliderPos.z,0},zero[4]={0,0,0,0};for(size_t i=0;i<N;i++){double force[3]={0,0,0};for(size_t j=0;j<N;j++)if(i!=j)sphereForce(s.pos.data()+4*i,s.pos.data()+4*j,s.prevel.data()+4*i,s.prevel.data()+4*j,p.particleRadius,p.particleRadius,p,force);sphereForce(s.pos.data()+4*i,cursor,s.prevel.data()+4*i,zero,p.particleRadius,p.colliderRadius,p,force);for(int k=0;k<3;k++)newvel[4*i+k]+=force[k];}s.vel.swap(newvel);}
inline void writeBlob(const char*name,const void*data,size_t bytes){FILE*f=fopen(name,"wb");if(!f)exit(3);if(fwrite(data,1,bytes,f)!=bytes)exit(3);fclose(f);}
